def transform(grid):
    left = [row[:4] for row in grid]
    right = [row[5:9] for row in grid]

    # If the two patterns overlap, retain the left pattern; otherwise combine them.
    overlaps = any(left[r][c] and right[r][c] for r in range(4) for c in range(4))
    if overlaps:
        return left
    return [
        [left[r][c] if left[r][c] else right[r][c] for c in range(4)]
        for r in range(4)
    ]
